-- Tabla nueva: tips (recomendaciones cortas, sin calificación) que un usuario deja sobre
-- un negocio. Fuente: data/tips.json. Ver docs/dominio_de_negocio.md §2-3 — 2239 filas.

CREATE TABLE tip (
    tip_id      INTEGER PRIMARY KEY,
    business_id TEXT NOT NULL REFERENCES business (business_id),
    user_id     TEXT NOT NULL REFERENCES users (user_id),
    tip_text    TEXT NOT NULL,
    tip_date    DATE NOT NULL,
    likes       INTEGER NOT NULL DEFAULT 0
);

CREATE INDEX idx_tip_business_id ON tip (business_id);
CREATE INDEX idx_tip_user_id     ON tip (user_id);

